// Tech/brand SVG icons — only loaded by lazy sections (Competencies, Projects, TechStack)

import type { CSSProperties, ReactNode } from "react";

export type TechIconVariant = "mono" | "brand";

export interface IconProps {
  size?: number;
  className?: string;
  weight?: string;
  title?: string;
  variant?: TechIconVariant;
  style?: CSSProperties;
}

function svgBase(
  props: IconProps,
  children: ReactNode,
  options?: {
    brandColor?: string;
    viewBox?: string;
    fill?: string;
  },
) {
  const { title, variant = "mono", style } = props;
  const mergedStyle = options?.brandColor
    ? ({ ...style, "--icon-brand": options.brandColor } as CSSProperties)
    : style;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={props.size ?? 24}
      height={props.size ?? 24}
      viewBox={options?.viewBox ?? "0 0 24 24"}
      fill={options?.fill ?? "currentColor"}
      className={props.className}
      style={mergedStyle}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
      data-variant={variant}
    >
      {title ? <title>{title}</title> : null}
      {children}
    </svg>
  );
}

function svg2(
  d: string,
  props: IconProps,
  options?: {
    brandColor?: string;
    viewBox?: string;
    fill?: string;
  },
) {
  return svgBase(props, <path d={d} />, options);
}

